const fs = require('fs');
const path = require('path');
const os = require('os');

// Global sliding-window request cap on the public webhook - not per-IP
// (n8n's Webhook node doesn't cleanly expose the caller's IP to a Code
// node), but it stops one bad actor (or a leaked demo-form token) from
// flooding Ollama/Airtable. Upgrade to a reverse-proxy rate limiter if
// this ever moves beyond localhost.
const baseDir = path.join(os.homedir(), 'inquiry-triage-data');
fs.mkdirSync(baseDir, { recursive: true });
const stateFile = path.join(baseDir, 'rate-limit-state.json');

const WINDOW_MS = 60 * 1000;
const MAX_REQUESTS = 10;

let history = [];
try {
  history = JSON.parse(fs.readFileSync(stateFile, 'utf-8'));
  if (!Array.isArray(history)) history = [];
} catch (e) {
  history = [];
}

const now = Date.now();
history = history.filter((t) => now - t < WINDOW_MS);

const overLimit = history.length >= MAX_REQUESTS;
if (!overLimit) {
  history.push(now);
}

fs.writeFileSync(stateFile, JSON.stringify(history), 'utf-8');

return [{ json: { ...$input.first().json, _rateLimited: overLimit ? 'true' : 'false' } }];

return [{
  json: {
    error: true,
    message: 'Too many requests - please wait a minute and try again.'
  }
}];

const input = $input.first().json;
const webhookData = $('Inquiry Webhook').first().json;
const originalMessage = (webhookData.body && webhookData.body.message) ? webhookData.body.message : '';
const name = (webhookData.body && webhookData.body.name) ? webhookData.body.name : '';
const email = (webhookData.body && webhookData.body.email) ? webhookData.body.email : '';

if (input.error) {
  const errText = JSON.stringify(input.error);
  const modelNotFound = /model .* not found/i.test(errText);
  const reason = modelNotFound
    ? 'The model set in the "Ollama Draft + Classify" node is not pulled on this machine. Run `ollama pull <model name>`, or edit the model field in that node to one you already have - see the README for picking a model based on your RAM.'
    : 'Could not reach Ollama - is it running? (' + input.error.message + ')';
  return [{
    json: {
      category: '',
      urgency: '',
      reply: '',
      valid: false,
      reasons: [reason],
      original_message: originalMessage,
      name,
      email,
      checked_at: new Date().toISOString()
    }
  }];
}

const raw = input.response || '';

const categoryMatch = raw.match(/CATEGORY:\s*(.+)/i);
const urgencyMatch = raw.match(/URGENCY:\s*(.+)/i);
const replyMatch = raw.match(/REPLY:\s*([\s\S]+)/i);

const category = categoryMatch ? categoryMatch[1].trim() : '';
const urgency = urgencyMatch ? urgencyMatch[1].trim() : '';
const reply = replyMatch ? replyMatch[1].trim() : '';

const reasons = [];

if (!originalMessage || !originalMessage.trim()) {
  reasons.push('No inquiry message received - malformed or empty webhook payload');
}

if (!category || !urgency || !reply) {
  reasons.push('Missing CATEGORY, URGENCY, or REPLY section - could not parse model output');
}

if (/\$\s?\d/.test(reply)) {
  reasons.push('Reply contains a dollar amount - no pricing promises allowed');
}

if (/\b\d{3}[-.]?\d{3}[-.]?\d{4}\b/.test(reply) || /\b[\w.+-]+@[\w-]+\.[a-zA-Z]{2,}\b/.test(reply)) {
  reasons.push('Reply may contain PII (phone number or email address)');
}

if (reply.length > 800) {
  reasons.push(`Reply too long (${reply.length} chars, cap is 800)`);
}

const disclaimer = 'This is an automated draft pending review by our team.';
if (!reply.includes(disclaimer)) {
  reasons.push('Required disclaimer sentence missing');
}

return [{
  json: {
    category,
    urgency,
    reply,
    valid: reasons.length === 0,
    reasons,
    original_message: originalMessage,
    name,
    email,
    checked_at: new Date().toISOString()
  }
}];

const items = $input.all();
const results = [];

for (const entry of items) {
  const item = entry.json;
  results.push({
    json: {
      Name: item.name || '',
      Email: item.email || '',
      Message: item.original_message || '',
      'Draft Reply': item.reply || '',
      Classification: item.category || '',
      Status: item.valid ? 'Needs Review' : 'Flagged',
      Date: item.checked_at,
    },
  });
}

return results;
